  --bg-primary:     #221627;
  --bg-secondary:   #2C1E33;
  --bg-tertiary:    #362840;
  --surface:        #3C2C48;

  --text-primary:   #DDD0E5;
  --text-secondary: #9880A8;
  --text-muted:     #6C5880;

  --border-strong:  #4E3868;
  --border-default: #402C58;
  --border-subtle:  #362840;

  --accent:         #B088D8;
  --accent-hover:   #C098E8;
  --accent-subtle:  #2C1E40;
  --accent-fg:      #1A1028;
}


/* ────────────────────────────────────────────────────────────────
   ROSÉA  —  Romantic · Soft · Warmth
   Draws from: Pink + Coral ramps
   Accent feel: Deep rose (passionate, tender)
   Contrast:    text-primary/bg-primary ≈ 9.8:1   (AAA)
                text-secondary/bg-primary ≈ 4.5:1  (AA)
──────────────────────────────────────────────────────────────── */
[data-theme="rosea"],
[data-theme="rosea"][data-mode="light"] {

  --bg-primary:     #FAF0F2;
  --bg-secondary:   #F5E5E8;
  --bg-tertiary:    #EED8DC;
  --surface:        #FFF5F6;

  --text-primary:   #3D2830;
  --text-secondary: #7A5860;
  --text-muted:     #A88088;

  --border-strong:  #C8A0A8;
  --border-default: #D4B0B8;
  --border-subtle:  #E0C4C8;

  --accent:         #A83048;
  --accent-hover:   #982038;
  --accent-subtle:  #FCE8EC;
  --accent-fg:      #FFFFFF;
}

[data-theme="rosea"][data-mode="dark"],
.dark [data-theme="rosea"] {

  --bg-primary:     #2A1A1E;
  --bg-secondary:   #342028;
  --bg-tertiary:    #3E2832;
  --surface:        #44303A;

  --text-primary:   #E8D0D5;
  --text-secondary: #A08088;
  --text-muted:     #706068;

  --border-strong:  #5A3840;
  --border-default: #4A2C34;
  --border-subtle:  #3E2832;

  --accent:         #E0788A;
  --accent-hover:   #F08898;
  --accent-subtle:  #3A2028;
  --accent-fg:      #200810;
}


/* ────────────────────────────────────────────────────────────────
   OBSIDIAN  —  Minimal · Editorial · Developer
   Draws from: Blue (desaturated) ramp
   Accent feel: Ink blue (focused, composed)
   Contrast:    text-primary/bg-primary ≈ 10.4:1  (AAA)
                text-secondary/bg-primary ≈ 5.1:1  (AA+)
──────────────────────────────────────────────────────────────── */
[data-theme="obsidian"],
[data-theme="obsidian"][data-mode="light"] {

  --bg-primary:     #F0F2F5;
  --bg-secondary:   #E8EBF0;
  --bg-tertiary:    #DDE0E8;
  --surface:        #F8F9FB;

  --text-primary:   #2A3040;
  --text-secondary: #5C6878;
  --text-muted:     #8898A8;

  --border-strong:  #A8B4C4;
  --border-default: #B8C2D0;
  --border-subtle:  #C8D0DC;

  --accent:         #2C4A6E;
  --accent-hover:   #1E3A5C;
  --accent-subtle:  #E4EAF4;
  --accent-fg:      #FFFFFF;
}

[data-theme="obsidian"][data-mode="dark"],
.dark [data-theme="obsidian"] {

  --bg-primary:     #1E2228;
  --bg-secondary:   #262C34;
  --bg-tertiary:    #2E3440;
  --surface:        #343C48;

  --text-primary:   #CDD2DB;
  --text-secondary: #7888A0;
  --text-muted:     #4E5C70;

  --border-strong:  #3C4858;
  --border-default: #2E3C4E;
  --border-subtle:  #2E3440;

  --accent:         #6898C8;
  --accent-hover:   #78A8D8;
  --accent-subtle:  #1E2C3A;
  --accent-fg:      #102030;
}


/* ================================================================
   §5  QUICK REFERENCE  —  All accent hex values at a glance
   ────────────────────────────────────────────────────────────────
   Theme    Light accent   Dark accent    Character
   ───────────────────────────────────────────────────
   Lumen    #4A5568        #8BACC0        Slate-blue, composed
   Terra    #8B5E3C        #D4956A        Burnt sienna, warm
   Verdant  #3A7A52        #70C088        Forest, grounded
   Aether   #1E5FAA        #6AAAD8        Ocean, confident
   Mystique #7038A8        #B088D8        Violet, expressive
   Roséa    #A83048        #E0788A        Deep rose, tender
   Obsidian #2C4A6E        #6898C8        Ink blue, focused
   ───────────────────────────────────────────────────
   Status colors are theme-agnostic (§2). They remain
   consistent to preserve universal meaning across themes.
================================================================= */


/* ================================================================
   §6  TYPOGRAPHY DEFAULTS  —  Base text rendering
   ────────────────────────────────────────────────────────────────
   Applied globally to all text elements for consistency and
   accessibility. Automatically inherits theme colors via CSS vars.
================================================================= */

html,
body {
  font-family: var(--font-default);
  font-size: 16px;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: var(--text-primary);
  background-color: var(--bg-primary);
}

/* Headings */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-default);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}

h1 { font-size: 2.5rem;   line-height: 1.2; }
h2 { font-size: 2rem;     line-height: 1.3; }
h3 { font-size: 1.75rem;  line-height: 1.3; }
h4 { font-size: 1.5rem;   line-height: 1.4; }
h5 { font-size: 1.25rem;  line-height: 1.4; }
h6 { font-size: 1rem;     line-height: 1.5; font-weight: 600; }

/* Paragraph & text elements */
p {
  margin-top: 0;
  margin-bottom: 1em;
  font-family: inherit;
  color: var(--text-primary);
}

span,
div,
li,
td,
th {
  font-family: inherit;
  color: var(--text-primary);
}

/* Form elements */
button,
input,
textarea,
select,
label {
  font-family: var(--font-default);
  color: var(--text-primary);
}

button {
  cursor: pointer;
  border: 1px solid var(--border-default);
  background-color: var(--bg-secondary);
  padding: 8px 16px;
  border-radius: 6px;
  transition: all 0.2s ease;
}

button:hover {
  background-color: var(--bg-tertiary);
  border-color: var(--border-default);
}

input,
textarea,
select {
  padding: 8px 12px;
  border: 1px solid var(--border-default);
  border-radius: 6px;
  background-color: var(--bg-secondary);
  transition: all 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-subtle);
}

/* Links */
a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

a:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Code & pre */
code,
pre {
  font-family: var(--font-mono);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  color: var(--text-primary);
}

code {
  padding: 2px 6px;
  font-size: 0.9em;
}

pre {
  padding: 1rem;
  overflow-x: auto;
  line-height: 1.5;
}

pre code {
  background: none;
  border: none;
  padding: 0;
}

/* Small text / captions */
small,
.caption,
.label {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Muted text */
.muted,
.placeholder {
  color: var(--text-muted);
}

/* Strong / Bold */
strong,
b {
  font-weight: 700;
}

/* Emphasis */
em,
i {
  font-style: italic;
}


/* ================================================================
   §7  TYPOGRAPHY UTILITY CLASSES  —  Optional semantic overrides
   ────────────────────────────────────────────────────────────────
   Use these classes to override the default font for specific
   sections or components. Example: <section class="font-editorial">
================================================================= */

.font-default {
  font-family: var(--font-default);
}

.font-modern {
  font-family: var(--font-modern);
}

.font-smooth {
  font-family: var(--font-smooth);
}

.font-tech {
  font-family: var(--font-tech);
}

.font-classic {
  font-family: var(--font-classic);
}

.font-serif {
  font-family: var(--font-serif);
}

.font-editorial {
  font-family: var(--font-editorial);
}

.font-accessibility {
  font-family: var(--font-accessibility);
}

.font-mono {
  font-family: var(--font-mono);
}

/* Icons */
.bi {
  font-family: var(--font-icon) !important;
}


/* ================================================================
   END OF THEME SYSTEM
================================================================= */

/* =============================================================
   LxCode Studio — Shared Design Tokens & Base Styles
   Loaded by: index.html (root) and all viewers via ../style.css
   ============================================================= */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  --bg:         #0d1117;
  --bg2:        #161b22;
  --bg3:        #21262d;
  --border:     #30363d;
  --text:       #e6edf3;
  --muted:      #7d8590;
  --dim:        #484f58;
  --accent:     #58a6ff;
  --accent-bg:  rgba(88, 166, 255, 0.1);
  --success:    #3fb950;
  --success-bg: rgba(63, 185, 80, 0.1);
  --warn:       #d29922;
  --warn-bg:    rgba(210, 153, 34, 0.12);
  --danger:     #f85149;
  --danger-bg:  rgba(248, 81, 73, 0.12);
  --radius:     6px;
  --radius-lg:  10px;
  --ui:         'DM Sans', sans-serif;
  --mono:       'JetBrains Mono', monospace;
  --hdr:        60px;
  --bar:        40px;
}

/* Light mode — toggled by body.light class (shared.js) */
body.light {
  --bg:         #f6f8fa;
  --bg2:        #ffffff;
  --bg3:        #eaeef2;
  --border:     #d0d7de;
  --text:       #1f2328;
  --muted:      #656d76;
  --dim:        #9198a1;
  --accent:     #0969da;
  --accent-bg:  rgba(9, 105, 218, 0.08);
}

/* ── Base ──────────────────────────────────────────────────── */
html, body {
  min-height: 100vh;
  font-family: var(--ui);
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  transition: background .2s, color .2s;
}
/* Viewer pages lock scroll via #layout — index scrolls freely */

/* ── Header ────────────────────────────────────────────────── */
#hdr {
  height: var(--hdr);
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 16px;
  gap: 8px;
}
/* Hub (index.html) header: taller + wider padding */
#hdr.hub {
  height: var(--hdr);
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 10;
}

/* ── Back button (viewer pages) ────────────────────────────── */
.back-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  text-decoration: none;
  font-size: 12px;
  font-weight: 500;
  padding: 4px 8px;
  border-radius: var(--radius);
  transition: color .12s, background .12s;
  flex-shrink: 0;
}
.back-btn:hover { color: var(--text); background: var(--bg3); }
.back-btn svg   { width: 14px; height: 14px; }

.hdr-div, .hdr-sep { width: 1px; height: 20px; background: var(--border); flex-shrink: 0; }
.hdr-right { margin-left: auto; display: flex; gap: 6px; align-items: center; }

/* ── Logo (index hub) ──────────────────────────────────────── */
.logo      { display: flex; align-items: center; gap: 10px; }
.logo-icon {
  width: 34px; height: 34px;
  background: linear-gradient(135deg, #58a6ff, #3fb950);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 12px; font-weight: 700; color: #fff;
}
.logo-name { font-weight: 700; font-size: 17px; letter-spacing: -.4px; }
.logo-sub  { font-size: 12px; color: var(--muted); font-weight: 500; }
.logo-ver  {
  font-size: 10px; color: var(--muted);
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: 20px; padding: 1px 8px;
  font-family: var(--mono);
}

/* ── Brand (viewer pages) ──────────────────────────────────── */
.brand      { display: flex; align-items: center; gap: 8px; }
.brand-icon {
  width: 26px; height: 26px;
  border-radius: var(--radius);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--mono); font-size: 10px; font-weight: 700;
  color: #fff; letter-spacing: -.3px; flex-shrink: 0;
}
.brand-name { font-weight: 600; font-size: 14px; letter-spacing: -.3px; }
.brand-sub  { font-size: 11px; color: var(--muted); display: none; }
@media (min-width: 600px) { .brand-sub { display: inline; } }

/* ── Theme toggle button (shared: hub + viewers) ───────────── */
.theme-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--bg3);
  color: var(--muted);
  font-family: var(--ui);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: color .12s, background .12s, border-color .12s;
  white-space: nowrap;
  flex-shrink: 0;
}
.theme-btn:hover { color: var(--text); border-color: var(--muted); }
.theme-btn svg   { width: 13px; height: 13px; flex-shrink: 0; }

/* ── Layout (viewer pages only) ───────────────────────────── */
#layout {
  display: flex;
  height: calc(100dvh - var(--hdr));
  overflow: hidden;
}
.panel  { display:flex; flex-direction:column; overflow:hidden; min-width:120px; }
.panel-left  { flex:0 0 50%; border-right:1px solid var(--border); }
.panel-right { flex:1 1 0; }
@media(max-width:767px) {
  #layout {
    flex-direction: column;
  }
  .panel-left{flex:0 0 50%;border-right:none;border-bottom:1px solid var(--border);}
  .panel-right{flex:1 1 0;}
}

/* ── Toolbar ───────────────────────────────────────────────── */
.toolbar {
  height: var(--bar);
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 10px;
  gap: 3px;
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.toolbar::-webkit-scrollbar { display: none; }
.tlabel {
  font-size: 10px; font-weight: 600; text-transform: uppercase;
  letter-spacing: .7px; color: var(--muted); flex-shrink: 0; margin-right: 4px;
  position: sticky; left: 0; background: var(--bg2); z-index: 1; padding: 10px 10px 10px 0;
}
.tsep { width: 1px; height: 16px; background: var(--border); margin: 0 4px; flex-shrink: 0; }
.tspc { background: transparent; margin: 0 4px; flex-shrink: 0; }

/* ── Buttons ───────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; gap: 4px;
  height: 26px; padding: 0 9px;
  background: transparent; border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--text); font-family: var(--ui); font-size: 11.5px; font-weight: 500;
  cursor: pointer; white-space: nowrap; flex-shrink: 0;
  transition: color .12s, background .12s, border-color .12s;
}
.btn:hover     { color: var(--text); background: var(--bg3); border-color: var(--border); }
.btn.active    { color: var(--accent); background: var(--accent-bg); border-color: var(--accent); }
.btn-icon      { width: 26px; padding: 0; justify-content: center; }
.btn-primary   { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { opacity: .85; color: #fff; }
.btn-run       { background: var(--success); border-color: var(--success); color: #fff; }
.btn-run:hover { opacity: .85; color: #fff; }
.btn svg       { width: 13px; height: 13px; flex-shrink: 0; }

/* ── Ace editor container ──────────────────────────────────── */
.ace-wrap { flex: 1; width: 100%; min-height: 0; overflow: hidden; }

/* ── Status bar ────────────────────────────────────────────── */
.statusbar {
  height: 22px;
  background: var(--bg2);
  border-top: 1px solid var(--border);
  display: flex; align-items: center;
  padding: 0 10px; gap: 12px;
  flex-shrink: 0; overflow: hidden;
}
.si { font-size: 10.5px; color: var(--dim); white-space: nowrap; }

/* ── Validation badge ──────────────────────────────────────── */
.vbadge {
  font-size: 10.5px; font-weight: 600;
  padding: 0 7px; height: 16px; border-radius: 20px;
  display: flex; align-items: center; gap: 4px;
  cursor: pointer; flex-shrink: 0; margin-left: auto;
}
.vbadge.ok   { background: var(--success-bg); color: var(--success); }
.vbadge.warn { background: var(--warn-bg);    color: var(--warn);    }
.vbadge.err  { background: var(--danger-bg);  color: var(--danger);  }
.vbadge svg  { width: 11px; height: 11px; }

/* ── Tooltip ───────────────────────────────────────────────── */
.vtip {
  position: fixed; bottom: 30px; right: 12px;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 10px 14px; max-width: 340px; max-height: 260px; overflow-y: auto;
  font-size: 11px; line-height: 1.6; z-index: 500;
  box-shadow: 0 8px 24px rgba(0,0,0,.35); display: none;
}
.vtip.show { display: block; }
.vtip ul   { padding-left: 14px; margin-top: 6px; }
.vtip li   { color: var(--muted); margin-bottom: 2px; }

/* ── Modal ─────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,.5);
  z-index: 400; display: none; align-items: center; justify-content: center;
}
.modal-overlay.open { display: flex; }
.modal-box {
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  width: min(420px, calc(100vw - 32px));
  box-shadow: 0 16px 48px rgba(0,0,0,.4);
  display: flex; flex-direction: column; gap: 12px;
}
.modal-box h3  { font-size: 13px; font-weight: 600; color: var(--text); }
.modal-row     { display: flex; gap: 7px; }
.modal-input   {
  flex: 1; height: 30px; padding: 0 10px;
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: var(--radius); color: var(--text);
  font-family: var(--ui); font-size: 12px; outline: none; min-width: 0;
}
.modal-input:focus        { border-color: var(--accent); }
.modal-input::placeholder { color: var(--dim); }
.modal-stat      { font-size: 11px; min-height: 16px; }
.modal-stat.ok   { color: var(--success); }
.modal-stat.err  { color: var(--danger); }
.modal-stat.load { color: var(--muted); }

/* ── Toast ─────────────────────────────────────────────────── */
#toast {
  position: fixed; bottom: 18px; right: 18px; z-index: 999;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 9px 14px; font-size: 12px; font-weight: 500; color: var(--text);
  box-shadow: 0 8px 24px rgba(0,0,0,.3);
  opacity: 0; transform: translateY(6px);
  transition: opacity .18s, transform .18s;
  pointer-events: none;
}
#toast.show { opacity: 1; transform: translateY(0); }
#toast.ok   { border-color: var(--success); color: var(--success); }
#toast.warn { border-color: var(--warn);    color: var(--warn);    }
#toast.err  { border-color: var(--danger);  color: var(--danger);  }

/* ═══════════════════════════════════════════════════════════
   INDEX HUB — Homepage-only styles
   ═══════════════════════════════════════════════════════════ */

/* Hub body allows scroll */
body.hub { overflow: auto; height: auto; }

/* ── Hub main wrapper ──────────────────────────────────────── */
.hub-main {
  max-width: 1060px;
  margin: 0 auto;
  padding: 56px 24px 80px;
}

/* ── Hero ──────────────────────────────────────────────────── */
.hero         { text-align: center; margin-bottom: 64px; }
.hero h1      { font-size: 36px; font-weight: 700; letter-spacing: -.6px; margin-bottom: 14px; line-height: 1.2; }
.hero h1 span { color: var(--accent); }
.hero p       { color: var(--muted); font-size: 15px; line-height: 1.7; max-width: 520px; margin: 0 auto; }

/* ── Product section ───────────────────────────────────────── */
.product-section { margin-bottom: 56px; }
.product-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}
.product-badge {
  width: 36px; height: 36px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.product-badge svg { width: 18px; height: 18px; color: #fff; }
.product-title { font-size: 20px; font-weight: 700; letter-spacing: -.3px; color: var(--text); }
.product-desc  { font-size: 13px; color: var(--muted); margin-top: 2px; }

/* ── Cards grid ────────────────────────────────────────────── */
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; }

.card {
  display: block; text-decoration: none;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 20px;
  transition: border-color .15s, transform .12s, box-shadow .15s;
  position: relative; overflow: hidden;
}
.card::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(135deg, var(--card-c1, #58a6ff), var(--card-c2, #3fb950));
  opacity: 0; transition: opacity .15s;
}
.card:hover { border-color: var(--card-c1, #58a6ff); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.15); }
.card:hover::before { opacity: .04; }
.card-icon {
  width: 38px; height: 38px; border-radius: 9px;
  background: linear-gradient(135deg, var(--card-c1, #58a6ff), var(--card-c2, #3fb950));
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px; position: relative;
  font-size: 11px; font-family: var(--mono); font-weight: 700;
  color: #fff; letter-spacing: -.3px;
}
.card-icon svg { width: 16px; height: 16px; color: #fff; }
.card-title    { font-weight: 600; font-size: 14px; margin-bottom: 6px; position: relative; color: var(--text); }
.card-desc     { font-size: 12px; color: var(--muted); line-height: 1.65; position: relative; }
.card-tags     { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 14px; position: relative; }
.tag {
  font-size: 10px; padding: 2px 8px; border-radius: 20px;
  background: var(--bg3); border: 1px solid var(--border); color: var(--muted);
}

/* ── Site footer ───────────────────────────────────────────── */
.site-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 40px 0 32px;
  font-size: 12px;
  color: var(--dim);
  border-top: 1px solid var(--border);
}
.footer-brand {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: 'Lobster', cursive;
  font-size: 1.13em;
}
.footer-logo {
  height: 14px;
  width: auto;
  vertical-align: middle;
}
@media (max-width: 599px) {
  .footer-sep { display: none; }
  .footer-tagline { display: block; width: 100%; text-align: center; }
}

