   ───────────────────────────────────────────────────
   Status colors are theme-agnostic (§2). They remain
   consistent to preserve universal meaning across themes.
================================================================= */


/* ================================================================
   §6  TYPOGRAPHY DEFAULTS  —  Base text rendering
   ────────────────────────────────────────────────────────────────
   Applied globally to all text elements for consistency and
   accessibility. Automatically inherits theme colors via CSS vars.
================================================================= */

html,
body {
  font-family: var(--font-default);
  font-size: 16px;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: var(--text-primary);
  background-color: var(--bg-primary);
}

/* Headings */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-default);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}

h1 { font-size: 2.5rem;   line-height: 1.2; }
h2 { font-size: 2rem;     line-height: 1.3; }
h3 { font-size: 1.75rem;  line-height: 1.3; }
h4 { font-size: 1.5rem;   line-height: 1.4; }
h5 { font-size: 1.25rem;  line-height: 1.4; }
h6 { font-size: 1rem;     line-height: 1.5; font-weight: 600; }

/* Paragraph & text elements */
p {
  margin-top: 0;
  margin-bottom: 1em;
  font-family: inherit;
  color: var(--text-primary);
}

span,
div,
li,
td,
th {
  font-family: inherit;
  color: var(--text-primary);
}

/* Form elements */
button,
input,
textarea,
select,
label {
  font-family: var(--font-default);
  color: var(--text-primary);
}

button {
  cursor: pointer;
  border: 1px solid var(--border-default);
  background-color: var(--bg-secondary);
  padding: 8px 16px;
  border-radius: 6px;
  transition: all 0.2s ease;
}

button:hover {
  background-color: var(--bg-tertiary);
  border-color: var(--border-default);
}

input,
textarea,
select {
  padding: 8px 12px;
  border: 1px solid var(--border-default);
  border-radius: 6px;
  background-color: var(--bg-secondary);
  transition: all 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-subtle);
}

/* Links */
a {
  color: var(--accent);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-hover);
  text-decoration: underline;
}

a:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Code & pre */
code,
pre {
  font-family: var(--font-mono);
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  color: var(--text-primary);
}

code {
  padding: 2px 6px;
  font-size: 0.9em;
}

pre {
  padding: 1rem;
  overflow-x: auto;
  line-height: 1.5;
}

pre code {
  background: none;
  border: none;
  padding: 0;
}

/* Small text / captions */
small,
.caption,
.label {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Muted text */
.muted,
.placeholder {
  color: var(--text-muted);
}

/* Strong / Bold */
strong,
b {
  font-weight: 700;
}

/* Emphasis */
em,
i {
  font-style: italic;
}


/* ================================================================
   §7  TYPOGRAPHY UTILITY CLASSES  —  Optional semantic overrides
   ────────────────────────────────────────────────────────────────
   Use these classes to override the default font for specific
   sections or components. Example: <section class="font-editorial">
================================================================= */

.font-default {
  font-family: var(--font-default);
}

.font-modern {
  font-family: var(--font-modern);
}

.font-smooth {
  font-family: var(--font-smooth);
}

.font-tech {
  font-family: var(--font-tech);
}

.font-classic {
  font-family: var(--font-classic);
}

.font-serif {
  font-family: var(--font-serif);
}

.font-editorial {
  font-family: var(--font-editorial);
}

.font-accessibility {
  font-family: var(--font-accessibility);
}

.font-mono {
  font-family: var(--font-mono);
}

/* Icons */
.bi {
  font-family: var(--font-icon) !important;
}


/* ================================================================
   END OF THEME SYSTEM
================================================================= */

