args.content:
/* 
  MINIMALIST OVERRIDES & ADAPTATIONS
  Integrating with themes.css semantic palette
*/
:root {
  /* Map LxREST variables to themes.css semantic variables */
  --bg: var(--bg-primary);
  --bg-alt: var(--bg-secondary);
  --border: var(--border-default);
  --text: var(--text-primary);
  --text-secondary: var(--text-secondary);
  --text-muted: var(--text-muted);

  /* Semantic mapping */
  --primary: var(--accent);
  --primary-hover: var(--accent-hover);
  --success: var(--success);
  --error: var(--error);
  --warning: var(--warning);

  /* Method mapping (from themes.css new additions) */
  --color-get: var(--method-get);
  --color-post: var(--method-post);
  --color-put: var(--method-put);
  --color-patch: var(--method-patch);
  --color-delete: var(--method-delete);

  /* UI Tokens */
  --radius: 8px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  --sidebar-width: 320px;
}

/* Reset some body defaults to match minimalist layout */
body {
  margin: 0;
  line-height: 1.5;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

/* LAYOUT & DRAWER */
.app {
  display: flex;
  height: 100vh;
  width: 100vw;
}

.sidebar-drawer {
  position: fixed;
  left: calc(var(--sidebar-width) * -1);
  top: 0;
  bottom: 0;
  width: var(--sidebar-width);
  background: var(--bg);
  border-right: 1px solid var(--border);
  z-index: 1000;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  visibility: hidden;
}

.sidebar-drawer.open {
  transform: translateX(var(--sidebar-width));
  box-shadow: 10px 0 30px rgba(0, 0, 0, 0.1);
  visibility: visible;
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: 24px;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
  z-index: 900;
}

.overlay.show {
  opacity: 1;
  pointer-events: auto;
}

/* COMPONENTS: HEADER */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
}

.brand {
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand span { color: var(--primary); }

.nav-actions {
  display: flex;
  gap: 8px;
}

/* COMPONENTS: BUTTONS */
button {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

button:hover {
  background: var(--border);
  color: var(--text);
}

button.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

button.primary:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

button.ghost {
  background: transparent;
  border-color: transparent;
}

button.ghost:hover {
  background: var(--bg-alt);
}

/* COMPONENTS: INPUT GROUP (REQUEST BAR) */
.request-bar {
  display: flex;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 4px;
  gap: 4px;
  margin-bottom: 24px;
  transition: var(--transition);
}

.request-bar:focus-within {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

.method-select {
  background: transparent;
  border: none;
  color: var(--text);
  font-weight: 700;
  font-size: 13px;
  padding: 0 12px;
  cursor: pointer;
  outline: none;
  text-transform: uppercase;
}

.url-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--text);
  font-family: inherit;
  font-size: 15px;
  padding: 8px 4px;
  outline: none;
}

/* COMPONENTS: TABS */
.tabs {
  display: flex;
  gap: 24px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
}

.tab {
  padding: 12px 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: var(--transition);
}

.tab.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.tab-content { display: none; padding: 12px 0; }
.tab-content.active { display: block; }

/* COMPONENTS: KEY-VALUE LIST */
.kv-row {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.kv-row input {
  flex: 1;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 8px 12px;
  border-radius: var(--radius);
  font-size: 13px;
  outline: none;
}

.kv-row input:focus { border-color: var(--primary); }

/* COMPONENTS: RESPONSE AREA */
.panel {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 24px;
  padding: 20px;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.meta-group {
  display: flex;
  gap: 16px;
  font-size: 12px;
  font-family: monospace;
}

.status-pill {
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
}

.status-ok { background: rgba(34, 197, 94, 0.1); color: var(--success); }
.status-err { background: rgba(239, 68, 68, 0.1); color: var(--error); }

pre {
  margin: 0;
  padding: 16px;
  background: var(--bg-alt);
  border-radius: var(--radius);
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 13px;
  overflow-x: auto;
  overflow-y: auto;
  max-height: 500px;
  border: 1px solid var(--border);
  color: var(--text-secondary);
}

textarea {
  width: 100%;
  min-height: 150px;
  max-height: 400px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 16px;
  border-radius: var(--radius);
  font-family: monospace;
  outline: none;
  resize: vertical;
}

/* SIDEBAR CONTENT REFINEMENT */
.sidebar-header {
  padding: 24px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.close-btn {
  width: 32px;
  height: 32px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  border: none;
  background: var(--bg-alt);
  color: var(--text-muted);
  cursor: pointer;
  transition: var(--transition);
}

.close-btn:hover {
  background: var(--border);
  color: var(--text);
  transform: rotate(90deg);
}

.sidebar-tabs {
  display: flex;
  padding: 0 20px 12px;
  gap: 4px;
  border-bottom: 1px solid var(--border);
}

.sidebar-tab {
  flex: 1;
  padding: 6px;
  text-align: center;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  border-radius: 4px;
  cursor: pointer;
  color: var(--text-muted);
  transition: var(--transition);
}

.sidebar-tab.active {
  background: var(--bg-alt);
  color: var(--primary);
}

.sidebar-body {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
}

.sidebar-body > * {
  animation: fadeInSide 0.4s ease forwards;
}

@keyframes fadeInSide {
  from { opacity: 0; transform: translateX(-10px); }
  to { opacity: 1; transform: translateX(0); }
}

.list-item {
  padding: 10px 12px;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: var(--transition);
}

.list-item:hover { background: var(--bg-alt); }

.list-item .method {
  font-size: 10px;
  font-weight: 800;
  min-width: 45px;
}

.list-item .url {
  font-size: 13px;
  color: var(--text-secondary);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* TOAST */
#toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(100px);
  background: var(--text);
  color: var(--bg);
  padding: 10px 20px;
  border-radius: 50px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: 0 10px 25px rgba(0,0,0,0.1);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1000;
}
#toast.show { transform: translateX(-50%) translateY(0); }

/* THEME TOGGLE SWITCH */
.theme-switch {
  position: relative;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  gap: 8px;
  padding: 4px;
}

.switch-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.switch-track {
  position: relative;
  width: 36px;
  height: 20px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 20px;
  transition: var(--transition);
}

.switch-track::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  background: var(--text-muted);
  border-radius: 50%;
  transition: var(--transition);
}

[data-mode="dark"] .switch-track {
  background: var(--primary);
  border-color: var(--primary);
}

[data-mode="dark"] .switch-track::after {
  left: 18px;
  background: white;
}

.hidden { display: none; }

