const $ = id => document.getElementById(id);

// State
let history = JSON.parse(localStorage.getItem('lxrest_history') || '[]');
let collections = JSON.parse(localStorage.getItem('lxrest_collections') || '[]');
let environments = JSON.parse(localStorage.getItem('lxrest_env') || '{"Default":{}}');
let currentEnv = localStorage.getItem('lxrest_current_env') || 'Default';
let sideActive = 'history';
let currentTheme = localStorage.getItem('lxrest_theme') || 'dark';

/* -----------------------------
   Initialization
----------------------------- */
function init() {
  setupTabs();
  renderSidebar();
  addKVRow('headersList', 'Content-Type', 'application/json');
  addKVRow('paramsList');
  applyTheme();
  updateMethodColor();

  // Keyboard Shortcuts
  window.onkeydown = e => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') executeRequest();
    if ((e.ctrlKey || e.metaKey) && e.key === 'b') beautifyJSON();
  };
}

/* -----------------------------
   UI Utilities
----------------------------- */
function toggleSidebar(show) {
  const sb = $('sidebar');
  const ov = $('overlay');

  if (show) {
    sb.classList.add('open');
    ov.classList.add('show');
  } else {
    sb.classList.remove('open');
    ov.classList.remove('show');
  }
}

function toggleTheme() {
  currentTheme = currentTheme === 'light' ? 'dark' : 'light';
  localStorage.setItem('lxrest_theme', currentTheme);
  applyTheme();
}

function applyTheme() {
  document.documentElement.setAttribute('data-mode', currentTheme);
  document.documentElement.setAttribute('data-theme', 'lumen');
  $('themeLabel').innerText = currentTheme === 'light' ? 'Light' : 'Dark';
}

function updateMethodColor() {
  const m = $('method').value;
  const colors = { GET: 'var(--color-get)', POST: 'var(--color-post)', PUT: 'var(--color-put)', PATCH: 'var(--color-patch)', DELETE: 'var(--color-delete)' };
  $('method').style.color = colors[m] || 'var(--text)';
}

function setupTabs() {
  document.querySelectorAll('.tab').forEach(tab => {
    tab.onclick = () => {
      const parent = tab.closest('.tabs');
      const container = parent.parentElement;
      const target = tab.dataset.target;
      parent.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      container.querySelectorAll('.tab-content').forEach(c => {
        if (c.parentElement === container) c.classList.remove('active');
      });
      tab.classList.add('active');
      $(target).classList.add('active');
    };
  });
}

/* -----------------------------
   Environment Helper
----------------------------- */
function replaceEnv(text) {
  if (!text) return text;
  const envData = environments[currentEnv] || {};
  return text.replace(/\{\{(.*?)\}\}/g, (match, key) => {
    return envData[key.trim()] !== undefined ? envData[key.trim()] : match;
  });
}

/* -----------------------------
   Sidebar Logic
----------------------------- */
function switchSideTab(type) {
  sideActive = type;
  document.querySelectorAll('.sidebar-tab').forEach(t => {
    t.classList.toggle('active', t.dataset.side === type);
  });
  renderSidebar();
}

function renderSidebar() {
  const cont = $('sidebarContent');
  cont.innerHTML = '';

  if (sideActive === 'history') {
    if (!history.length) return cont.innerHTML = '<div style="padding:20px; color:var(--text-muted); font-size:12px; text-align:center;">No history yet</div>';
    history.forEach(item => {
      const el = createListItem(item.method, item.url, () => { loadRequest(item); toggleSidebar(false); });
      cont.appendChild(el);
    });
  } else if (sideActive === 'collections') {
    if (!collections.length) return cont.innerHTML = '<div style="padding:20px; color:var(--text-muted); font-size:12px; text-align:center;">No collections</div>';
    collections.forEach(item => {
      const el = createListItem(item.method, item.name || item.url, () => { loadRequest(item); toggleSidebar(false); });
      cont.appendChild(el);
    });
  } else if (sideActive === 'env') {
    renderEnvEditor(cont);
  }
}

function createListItem(method, title, onclick) {
  const el = document.createElement('div');
  el.className = 'list-item';
  const colorMap = { GET: 'var(--color-get)', POST: 'var(--color-post)', PUT: 'var(--color-put)', PATCH: 'var(--color-patch)', DELETE: 'var(--color-delete)' };
  el.innerHTML = `<span class="method" style="color: ${colorMap[method]}">${method}</span><span class="url">${title}</span>`;
  el.onclick = onclick;
  return el;
}

function renderEnvEditor(container) {
  const envs = Object.keys(environments);
  const envOptions = envs.map(e => `<option value="${e}" ${e === currentEnv ? 'selected' : ''}>${e}</option>`).join('');
  const currentEnvData = JSON.stringify(environments[currentEnv], null, 2);

  container.innerHTML = `
    <div style="padding: 12px;">
      <select onchange="switchEnv(this.value)" style="width:100%; background:var(--bg-alt); border:1px solid var(--border); color:var(--text); padding:8px; border-radius:var(--radius); margin-bottom:12px;">
        ${envOptions}
      </select>
      <textarea id="envJson" style="font-size:12px; min-height:200px; width:100%;">${currentEnvData}</textarea>
      <button class="primary" style="width:100%; margin-top:8px;" onclick="saveEnv()">Save Environment</button>
      <button class="ghost" style="width:100%; margin-top:4px;" onclick="addEnv()">+ New Environment</button>
    </div>
  `;
}

/* -----------------------------
   Core Network Logic
----------------------------- */
async function executeRequest() {
  const method = $('method').value;
  const urlRaw = replaceEnv($('url').value.trim());
  const bodyRaw = replaceEnv($('body').value.trim());

  if (!urlRaw) return showToast('URL is required');

  const sendBtn = $('sendBtn');
  sendBtn.disabled = true;
  sendBtn.innerText = 'Sending...';
  $('responseBody').innerText = '// Loading...';

  const startTime = performance.now();

  try {
    const urlObj = new URL(urlRaw.startsWith('http') ? urlRaw : `https://${urlRaw}`);
    const params = collectKV('paramsList');
    Object.entries(params).forEach(([k, v]) => urlObj.searchParams.append(replaceEnv(k), replaceEnv(v)));

    const headers = collectKV('headersList');
    const finalHeaders = {};
    Object.entries(headers).forEach(([k, v]) => finalHeaders[replaceEnv(k)] = replaceEnv(v));

    const authType = $('authType').value;
    if (authType === 'bearer') finalHeaders['Authorization'] = `Bearer ${replaceEnv($('bearerToken').value.trim())}`;
    else if (authType === 'basic') finalHeaders['Authorization'] = `Basic ${btoa(replaceEnv($('basicUser').value) + ':' + replaceEnv($('basicPass').value))}`;

    const options = { method, headers: finalHeaders };
    if (!['GET', 'HEAD'].includes(method) && bodyRaw) options.body = bodyRaw;

    const response = await fetch(urlObj, options);
    const duration = Math.round(performance.now() - startTime);
    const text = await response.text();
    const size = new TextEncoder().encode(text).length;

    renderResponse(response, text, duration, size);
    saveToHistory(method, urlObj.toString());

  } catch (err) {
    $('responseBody').innerText = `// Error: ${err.message}`;
    showToast('Network Error');
  } finally {
    sendBtn.disabled = false;
    sendBtn.innerText = 'Send';
  }
}

function renderResponse(res, text, duration, size) {
  const sl = $('statusLabel');
  sl.innerText = `${res.status} ${res.statusText}`;
  sl.className = `status-pill ${res.ok ? 'status-ok' : 'status-err'}`;
  sl.classList.remove('hidden');

  $('timeLabel').innerText = `${duration}ms`;
  $('timeLabel').classList.remove('hidden');
  $('sizeLabel').innerText = formatSize(size);
  $('sizeLabel').classList.remove('hidden');

  try {
    $('responseBody').innerText = JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    $('responseBody').innerText = text || '// Empty body';
  }

  let hStr = '';
  res.headers.forEach((v, k) => hStr += `${k}: ${v}\n`);
  $('responseHeaders').innerText = hStr || '// No headers';
}

/* -----------------------------
   Persistence
----------------------------- */
function saveToHistory(method, url) {
  const item = { method, url, timestamp: Date.now(), headers: collectKV('headersList'), params: collectKV('paramsList'), body: $('body').value };
  if (history[0]?.url === url && history[0]?.method === method) return;
  history.unshift(item);
  history = history.slice(0, 50);
  localStorage.setItem('lxrest_history', JSON.stringify(history));
  if (sideActive === 'history') renderSidebar();
}

function saveToCollection() {
  const name = prompt('Request Name:', $('url').value);
  if (!name) return;
  const item = { name, method: $('method').value, url: $('url').value, body: $('body').value, headers: collectKV('headersList'), params: collectKV('paramsList') };
  collections.unshift(item);
  localStorage.setItem('lxrest_collections', JSON.stringify(collections));
  showToast('Saved');
  if (sideActive === 'collections') renderSidebar();
}

function loadRequest(item) {
  $('method').value = item.method;
  $('url').value = item.url;
  $('body').value = item.body || '';
  if (item.params) {
    $('paramsList').innerHTML = '';
    Object.entries(item.params).forEach(([k, v]) => addKVRow('paramsList', k, v));
  }
  if (item.headers) {
    $('headersList').innerHTML = '';
    Object.entries(item.headers).forEach(([k, v]) => addKVRow('headersList', k, v));
  }
  updateMethodColor();
  showToast('Loaded');
}

/* -----------------------------
   Helpers & Utils
----------------------------- */
function addKVRow(listId, key = '', value = '') {
  const row = document.createElement('div');
  row.className = 'kv-row';
  row.innerHTML = `<input type="text" placeholder="Key" value="${key}"><input type="text" placeholder="Value" value="${value}"><button class="ghost" onclick="this.parentElement.remove()" style="padding:4px">&times;</button>`;
  $(listId).appendChild(row);
}

function collectKV(listId) {
  const res = {};
  document.querySelectorAll(`#${listId} .kv-row`).forEach(row => {
    const inputs = row.querySelectorAll('input');
    if (inputs[0].value) res[inputs[0].value] = inputs[1].value;
  });
  return res;
}

function beautifyJSON() {
  try {
    const b = $('body');
    b.value = JSON.stringify(JSON.parse(b.value), null, 2);
  } catch { showToast('Invalid JSON'); }
}

function copyAsCurl() {
  const method = $('method').value;
  const url = $('url').value;
  const headers = collectKV('headersList');
  let curl = `curl -X ${method} "${url}"`;
  Object.entries(headers).forEach(([k, v]) => curl += ` -H "${k}: ${v}"`);
  const body = $('body').value.trim();
  if (body && method !== 'GET') curl += ` -d '${body.replace(/'/g, "'\\''")}'`;
  navigator.clipboard.writeText(curl).then(() => showToast('cURL Copied!'));
}

function showToast(m) {
  const t = $('toast'); t.innerText = m; t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2000);
}

function formatSize(b) {
  if (b < 1024) return b + ' B';
  return (b/1024).toFixed(1) + ' KB';
}

function clearSidebar() {
  if (confirm('Clear history?')) {
    history = [];
    localStorage.setItem('lxrest_history', '[]');
    renderSidebar();
  }
}

function toggleAuthFields() {
  const type = $('authType').value;
  $('authBearer').classList.toggle('hidden', type !== 'bearer');
  $('authBasic').classList.toggle('hidden', type !== 'basic');
}

function switchEnv(name) {
  currentEnv = name;
  localStorage.setItem('lxrest_current_env', name);
  renderSidebar();
}

function saveEnv() {
  try {
    environments[currentEnv] = JSON.parse($('envJson').value);
    localStorage.setItem('lxrest_env', JSON.stringify(environments));
    showToast('Env Saved');
  } catch { showToast('Invalid JSON'); }
}

function addEnv() {
  const name = prompt('Env Name:');
  if (!name) return;
  environments[name] = {};
  switchEnv(name);
}

init();

